// TRUSTED configuration. Meeting notes cannot override these settings.
const settings = {
  enable_gmail: false,
  reviewer_email: '', // YOUR test/reviewer inbox; never an address copied from the notes.
  draft_recipient: '', // YOUR test inbox. Final follow-up is saved as a draft, not sent.
  max_versions: 3, // Initial draft plus at most TWO revisions across all feedback paths.
  quality_threshold: 4.5, // Design choice on a 1-5 scale; NOT a probability of correctness.
  audience: 'Internal project team',
  max_draft_words: 220,
  test_fixture: 'none', // Only alternative: omit_last_action_line_v1 (controlled negative test).
};
return [{json:{...$input.first().json,settings},pairedItem:{item:0}}];

// Prepare Input: normalise the chat message, keep the full current notes as raw_notes, reject empty / oversized input.
const MAX_CHARS = 12000;
const MIN_CHARS = 20;
const MIN_WORDS = 4;
const item = $input.first().json || {};
const chatInput = typeof item.chatInput === 'string' ? item.chatInput : '';
const sessionId = item.sessionId !== undefined ? item.sessionId : null;
const raw_notes = chatInput.trim();
// Origin/job linkage. Only the website lane sets WEBSITE_API; chat runs never read webhook output.
const input_origin = item.input_origin === 'WEBSITE_API' ? 'WEBSITE_API' : 'CHAT';
const job_id = input_origin === 'WEBSITE_API' && typeof item.job_id === 'string' ? item.job_id : null;
const request_id = input_origin === 'WEBSITE_API' && typeof item.request_id === 'string' ? item.request_id : null;
const requested_period = input_origin === 'WEBSITE_API' ? { start: item.period_start || null, end: item.period_end || null, timezone: item.timezone || null } : null;

let input_valid = true;
let input_error = null;
let input_error_code = null;

if (raw_notes.length === 0) {
  input_valid = false;
  input_error_code = 'EMPTY_INPUT';
  input_error = 'No meeting notes were received.';
} else if (raw_notes.length < MIN_CHARS || raw_notes.split(/\s+/).length < MIN_WORDS) {
  input_valid = false;
  input_error_code = 'TOO_SHORT';
  input_error = 'The message is too short to be meeting notes.';
} else if (raw_notes.length > MAX_CHARS) {
  input_valid = false;
  input_error_code = 'TOO_LONG';
  input_error = 'The notes are ' + raw_notes.length + ' characters, which is over the ' + MAX_CHARS + '-character limit. Nothing was truncated.';
}

const out = { settings: item.settings, case_id: 'AR2-' + String($execution.id), chatInput, sessionId, raw_notes, raw_length: raw_notes.length, input_origin, job_id, request_id, requested_period, input_valid, input_ok: input_valid, input_error, input_error_code };
if (!input_valid) out.route = 'NEEDS_CLARIFICATION';
return [{ json: out }];

// This node runs once for each version. Use linked items after each agent, not .first() on loops.
const x=$input.first().json;
const s=x.version ? x : {...x, version:1, history:[], events:[], feedback:[], feedback_log:[], previous_candidate:null};
if (!Number.isInteger(s.version) || s.version<1 || s.version>s.settings.max_versions) throw new Error('Version budget invalid. Stop for manual review.');
const payload={
  case_id:s.case_id, version:s.version,
  task:'Extract confirmed commitments and write a concise meeting follow-up DRAFT, never an approved or sent message.',
  current_notes:s.raw_notes,
  audience:s.settings.audience,
  max_draft_words:s.settings.max_draft_words,
  previous_candidate:s.previous_candidate,
  requested_changes:s.feedback || [],
  human_editorial_feedback:(s.feedback_log||[]).filter(e=>e.source==='human_reviewer').flatMap(e=>e.comments),
};
return [{json:{...s,writer_payload:JSON.stringify(payload)},pairedItem:{item:0}}];

// Preserve the state that produced THIS version, including real tool steps.
const state=$('Prepare Writer Input').item.json;
const agent=$input.first().json;
return [{json:{...agent,_state:state},pairedItem:{item:0}}];

// Week 1 validation retained; strict margin evidence and null-output guard added.
const incoming=$input.first().json;
const state=incoming._state || $('Prepare Input').first().json;
const checked=(()=>{
// Validate and Audit: parse the agent output safely, validate the schema, check quotes against raw_notes,
// recompute numbers independently, read the real Calculator trace, and decide the route. No eval, no model calls.
const WS = (s) => String(s).replace(/\s+/g, ' ').trim();
const isStr = (v) => typeof v === 'string';
const nz = (v) => isStr(v) && v.trim() !== '';
const strOrNull = (v) => v === null || isStr(v);
const hoursOk = (v) => v === null || (typeof v === 'number' && Number.isFinite(v) && v >= 0);
const round = (n) => Math.round(n * 1e6) / 1e6;
const fmt = (n) => (n === null || n === undefined ? 'Not specified' : String(round(n)));
const close = (a, b) => Math.abs(a - b) < 1e-6;
const MISSING_WORDS = new Set(['', 'someone', 'somebody', 'anyone', 'nobody', 'unassigned', 'tbd', 'tba', 'unknown', 'not specified', 'n/a', 'na', 'none', 'null']);
const cleanOrNull = (v) => (isStr(v) && !MISSING_WORDS.has(v.trim().toLowerCase()) ? v.trim() : null);
// Deadline grounding (safety fix): conservative token normalisation = lowercase, punctuation/whitespace -> single space. No date conversion or inference.
const normTok = (v) => ' ' + String(v === null || v === undefined ? '' : v).toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim() + ' ';
const NOT_AGREED_DUE = /^(?:no|not|without|none)\b.*\b(?:deadline|due|date|agreed|set|decided|confirmed)\b|^(?:to be|yet to be|still to be) (?:decided|confirmed|agreed|determined|set|scheduled)\b|^(?:undecided|unscheduled|pending|open|tbc)$/;
const dueOrNull = (v) => { const c = cleanOrNull(v); return c !== null && NOT_AGREED_DUE.test(normTok(c).trim()) ? null : c; };
const normPeriod = (p) => (nz(p) ? p.toLowerCase().replace(/[\u2012-\u2015\u2212]/g, '-').replace(/\s*-\s*/g, '-').replace(/[^a-z0-9-]+/g, ' ').replace(/\s+/g, ' ').trim() : null);
const samePeriod = (a, b) => { const x = normPeriod(a); const y = normPeriod(b); return x !== null && y !== null && x === y; };
const cell = (v) => String(v === null || v === undefined || v === '' ? 'Not specified' : v).replace(/\|/g, '\\|').replace(/\s+/g, ' ').trim();
const clip = (s, n) => { const t = WS(s || ''); return t.length > n ? t.slice(0, n - 3) + '...' : t; };

const prep = $('Prepare Input').first().json || {};
const raw_notes = typeof prep.raw_notes === 'string' ? prep.raw_notes : '';
const j = $input.first().json || {};

// Input rejected upstream (empty or too long): the agent was bypassed. Route straight to clarification; no meeting is invented.
if (prep.input_valid === false) {
  return [{ json: {
    route: 'NEEDS_CLARIFICATION', status: 'Needs clarification - no plan was generated (not approved)',
    input_valid: false, input_error: prep.input_error, input_error_code: prep.input_error_code,
    technical_issues: [],
    business_issues: [{ code: prep.input_error_code || 'INPUT_REJECTED', message: prep.input_error || 'The notes could not be used.' }],
    questions: ['Please send the complete meeting notes, including owners, deadlines, estimated work-hours, and any stated capacity.'],
    meeting_title: null, actions: [], sections: null,
    audit: { schema_valid: false, agent_bypassed: true }, raw_model_output: '',
  } }];
}

const tech = [];
const biz = [];
const addTech = (category, message) => tech.push({ category, message });

// 1. Execution failure (native error output of the agent)
if (j.error) {
  const m = typeof j.error === 'string' ? j.error : (j.error && (j.error.message || j.error.description)) || 'Unknown error';
  addTech('EXECUTION_FAILURE', 'The model or a tool failed to run: ' + clip(m, 200));
}

// 2. Safe parse (no eval)
const rawOut = typeof j.output === 'string' ? j.output : (j.output !== undefined && j.output !== null ? JSON.stringify(j.output) : '');
let plan = null;
if (!j.error) {
  let txt = rawOut.trim();
  const fence = txt.match(/^```(?:json)?\s*([\s\S]*?)\s*```$/i);
  if (fence) txt = fence[1];
  if (txt === '') {
    addTech('MALFORMED_OUTPUT', 'The model returned no output.');
  } else {
    try { plan = JSON.parse(txt); } catch (e) { addTech('MALFORMED_OUTPUT', 'The model output was not valid JSON.'); }
    if (plan === null && !tech.length) addTech('MALFORMED_OUTPUT', 'The model returned JSON null.');
    if (plan !== null && (typeof plan !== 'object' || Array.isArray(plan))) { addTech('MALFORMED_OUTPUT', 'The model output was not a JSON object.'); plan = null; }
  }
}

// 3. Schema validation
let schemaOk = false;
const quoteChecks = { checked: 0, mismatches: [] };
const deadlineCheck = { checked: 0, unsupported: [] };
let actions = [];
let decisions = [];
let conflicts = [];
let modelQuestions = [];
let team = { hours: null, period: null, source_quote: null };
let ownerCaps = [];
let planningPeriod = null;
let meetingTitle = null;

if (plan) {
  const errs = [];
  const need = (cond, msg) => { if (!cond) errs.push(msg); };
  need(strOrNull(plan.meeting_title), 'meeting_title must be a string or null');
  need(strOrNull(plan.planning_period), 'planning_period must be a string or null');
  for (const k of ['decisions', 'actions', 'owner_capacities', 'conflicts', 'questions']) need(Array.isArray(plan[k]), k + ' must be an array');
  const tc = plan.team_capacity;
  need(tc && typeof tc === 'object' && !Array.isArray(tc), 'team_capacity must be an object');
  if (tc && typeof tc === 'object' && !Array.isArray(tc)) {
    need(hoursOk(tc.hours === undefined ? null : tc.hours), 'team_capacity.hours must be a finite number >= 0 or null');
    need(strOrNull(tc.period === undefined ? null : tc.period), 'team_capacity.period must be a string or null');
    need(strOrNull(tc.source_quote === undefined ? null : tc.source_quote), 'team_capacity.source_quote must be a string or null');
    if (typeof tc.hours === 'number') need(nz(tc.source_quote), 'team_capacity.hours needs a source_quote');
  }
  if (Array.isArray(plan.decisions)) plan.decisions.forEach((d, i) => { need(d && nz(d.text), 'decisions[' + i + '].text must be non-empty'); need(d && nz(d.source_quote), 'decisions[' + i + '].source_quote must be non-empty'); });
  if (Array.isArray(plan.actions)) {
    const ids = new Set();
    plan.actions.forEach((a, i) => {
      if (!a || typeof a !== 'object') { errs.push('actions[' + i + '] must be an object'); return; }
      need(nz(a.id), 'actions[' + i + '].id must be non-empty');
      if (nz(a.id)) { need(!ids.has(a.id), 'duplicate action id ' + a.id); ids.add(a.id); }
      need(nz(a.task), 'actions[' + i + '].task must be non-empty');
      need(strOrNull(a.owner === undefined ? null : a.owner), 'actions[' + i + '].owner must be a string or null');
      need(strOrNull(a.due_text === undefined ? null : a.due_text), 'actions[' + i + '].due_text must be a string or null');
      need(hoursOk(a.estimated_hours === undefined ? null : a.estimated_hours), 'actions[' + i + '].estimated_hours must be a finite number >= 0 or null');
      need(nz(a.source_quote), 'actions[' + i + '].source_quote must be non-empty');
    });
  }
  if (Array.isArray(plan.owner_capacities)) plan.owner_capacities.forEach((o, i) => {
    need(o && nz(o.owner), 'owner_capacities[' + i + '].owner must be non-empty');
    need(o && typeof o.hours === 'number' && Number.isFinite(o.hours) && o.hours >= 0, 'owner_capacities[' + i + '].hours must be a finite number >= 0');
    need(o && strOrNull(o.period === undefined ? null : o.period), 'owner_capacities[' + i + '].period must be a string or null');
    need(o && nz(o.source_quote), 'owner_capacities[' + i + '].source_quote must be non-empty');
  });
  if (Array.isArray(plan.conflicts)) plan.conflicts.forEach((c, i) => { need(c && nz(c.issue), 'conflicts[' + i + '].issue must be non-empty'); need(c && strOrNull(c.source_quote === undefined ? null : c.source_quote), 'conflicts[' + i + '].source_quote must be a string or null'); });
  if (Array.isArray(plan.questions)) plan.questions.forEach((q, i) => need(nz(q), 'questions[' + i + '] must be a non-empty string'));
  if (errs.length) {
    addTech('SCHEMA_INVALID', 'Required fields are invalid: ' + errs.slice(0, 6).join('; ') + (errs.length > 6 ? ' (+' + (errs.length - 6) + ' more)' : '') + '.');
  } else {
    schemaOk = true;
    meetingTitle = plan.meeting_title;
    planningPeriod = plan.planning_period;
    decisions = plan.decisions;
    conflicts = plan.conflicts;
    modelQuestions = plan.questions;
    team = { hours: tc.hours === undefined ? null : tc.hours, period: tc.period === undefined ? null : tc.period, source_quote: tc.source_quote === undefined ? null : tc.source_quote };
    ownerCaps = plan.owner_capacities.map((o) => ({ owner: o.owner.trim(), hours: o.hours, period: o.period === undefined ? null : o.period, source_quote: o.source_quote }));
    actions = plan.actions.map((a) => ({
      id: a.id.trim(), task: a.task.trim(), owner: cleanOrNull(a.owner), due_text: dueOrNull(a.due_text),
      estimated_hours: a.estimated_hours === undefined ? null : a.estimated_hours, source_quote: a.source_quote,
    }));
  }
}

// 4. Source quote check (excerpt occurs in the CURRENT raw_notes after whitespace normalisation)
if (schemaOk) {
  const normNotes = WS(raw_notes);
  const chk = (where, q) => { if (!nz(q)) return; quoteChecks.checked++; if (!normNotes.includes(WS(q))) quoteChecks.mismatches.push({ where, quote: clip(q, 80) }); };
  decisions.forEach((d, i) => chk('decision ' + (i + 1), d.source_quote));
  actions.forEach((a) => chk('action ' + a.id, a.source_quote));
  if (team.hours !== null || nz(team.source_quote)) chk('team capacity', team.source_quote);
  ownerCaps.forEach((o) => chk('capacity for ' + o.owner, o.source_quote));
  conflicts.forEach((c, i) => chk('conflict ' + (i + 1), c.source_quote));
  if (quoteChecks.mismatches.length) {
    addTech('QUOTE_MISMATCH', quoteChecks.mismatches.length + ' source quote(s) were not found in the current notes (' + quoteChecks.mismatches.map((m) => m.where).slice(0, 6).join(', ') + ').');
  }
  // 4b. Deadline grounding: a non-null due_text must occur (token-bounded) inside its OWN source_quote, and that quote must occur in the current notes.
  actions.forEach((a) => {
    if (a.due_text === null) return;
    deadlineCheck.checked++;
    const quoteInNotes = nz(a.source_quote) && normNotes.includes(WS(a.source_quote));
    const inQuote = nz(a.source_quote) && normTok(a.source_quote).includes(normTok(a.due_text));
    if (!quoteInNotes || !inQuote) deadlineCheck.unsupported.push({ action: a.id, due_text: clip(a.due_text, 60), reason: !quoteInNotes ? 'source quote not found in the current notes' : 'deadline wording not found in the action source quote' });
  });
  if (deadlineCheck.unsupported.length) {
    addTech('DEADLINE_UNSUPPORTED', deadlineCheck.unsupported.length + ' deadline(s) are not supported by the source: ' + deadlineCheck.unsupported.slice(0, 6).map((d) => d.action + ' "' + d.due_text + '" (' + d.reason + ')').join('; ') + '. Deadlines are never inferred.');
  }
}

// 5. Independent calculations from extracted numeric fields
const audit = {
  schema_valid: schemaOk, action_count: actions.length, missing_owner_count: 0, missing_deadline_count: 0,
  known_effort_subtotal: null, actions_without_estimate: 0, full_workload_assessable: false,
  team_capacity_comparable: false, team_margin: null, team_overload: false,
  owner_workloads: [], calculator_required: false, calculator_called: false, calculator_calls: [],
  calculator_observed_result: null, calculator_margin_observed: null, calculator_failed_calls: 0,
  quote_check: { checked: quoteChecks.checked, mismatches: quoteChecks.mismatches },
  deadline_check: deadlineCheck,
};

let knownSubtotal = 0;
let teamComparable = false;
const ownerRows = [];

if (schemaOk) {
  audit.missing_owner_count = actions.filter((a) => a.owner === null).length;
  audit.missing_deadline_count = actions.filter((a) => a.due_text === null).length;
  const est = actions.filter((a) => a.estimated_hours !== null);
  audit.actions_without_estimate = actions.length - est.length;
  knownSubtotal = round(est.reduce((s, a) => s + a.estimated_hours, 0));
  audit.known_effort_subtotal = est.length ? knownSubtotal : null;
  audit.full_workload_assessable = actions.length > 0 && audit.actions_without_estimate === 0;

  // Team capacity (only for a comparable planning period)
  if (team.hours !== null) {
    if (samePeriod(team.period, planningPeriod)) {
      teamComparable = true;
      audit.team_capacity_comparable = true;
      audit.team_margin = round(team.hours - knownSubtotal);
      audit.team_overload = knownSubtotal > team.hours;
    } else {
      biz.push({ code: 'CAPACITY_PERIOD_AMBIGUOUS', message: 'Team capacity period (' + (team.period || 'not stated') + ') cannot be matched to the planning period (' + (planningPeriod || 'not stated') + '), so team capacity was not assessed.', question: 'Does the ' + fmt(team.hours) + '-hour team capacity cover the same tasks and planning period as these actions?' });
    }
  }

  // Effort grouped by owner (owner capacities and team capacity are never added together)
  const groups = new Map();
  actions.forEach((a) => {
    if (a.owner === null) return;
    const k = a.owner.toLowerCase();
    if (!groups.has(k)) groups.set(k, { owner: a.owner, known: 0, missing: 0, count: 0 });
    const g = groups.get(k);
    g.count++;
    if (a.estimated_hours === null) g.missing++; else g.known = round(g.known + a.estimated_hours);
  });
  groups.forEach((g, k) => {
    const caps = ownerCaps.filter((o) => o.owner.toLowerCase() === k);
    const row = { owner: g.owner, actions: g.count, known_hours: g.known, actions_without_estimate: g.missing, capacity_hours: null, status: 'NO_CAPACITY_SUPPLIED', over_by: null };
    if (caps.length) {
      const comparable = caps.filter((o) => samePeriod(o.period, planningPeriod));
      const distinct = Array.from(new Set(comparable.map((o) => o.hours)));
      if (!comparable.length) {
        row.status = 'PERIOD_AMBIGUOUS';
        biz.push({ code: 'CAPACITY_PERIOD_AMBIGUOUS', message: g.owner + "'s capacity period (" + (caps[0].period || 'not stated') + ') cannot be matched to the planning period, so it was not assessed.', question: 'Does ' + g.owner + "'s " + fmt(caps[0].hours) + ' available hours cover the same tasks and planning period?' });
      } else if (distinct.length > 1) {
        row.status = 'CONFLICTING_CAPACITY';
        biz.push({ code: 'CONFLICT', message: g.owner + ' has conflicting capacity figures (' + distinct.join(' vs ') + ' hours).', question: 'Which available-hours figure applies to ' + g.owner + '?' });
      } else {
        row.capacity_hours = distinct[0];
        if (g.known > row.capacity_hours) {
          row.status = 'OVERLOAD'; row.over_by = round(g.known - row.capacity_hours);
          biz.push({ code: 'INDIVIDUAL_OVERLOAD', message: g.owner + ': ' + fmt(g.known) + ' h' + (g.missing ? ' (known subtotal)' : '') + ' of estimated effort vs ' + fmt(row.capacity_hours) + ' h available (over by ' + fmt(row.over_by) + ' h).', question: g.owner + ' is over their available hours by ' + fmt(row.over_by) + ' h. Which task, estimate, or availability should change? (Nothing has been reassigned.)' });
        } else if (g.missing > 0) {
          row.status = 'INCOMPLETE_ESTIMATES';
        } else {
          row.status = 'WITHIN_CAPACITY';
        }
      }
    }
    ownerRows.push(row);
  });
  audit.owner_workloads = ownerRows;
}

// 6. Read the ACTUAL Calculator trace from the agent's intermediate steps
if (schemaOk) {
  const steps = Array.isArray(j.intermediateSteps) ? j.intermediateSteps : [];
  const calc = steps.filter((s) => s && s.action && /calculator/i.test(String(s.action.tool || ''))).map((s) => {
    let o = s.observation;
    if (typeof o === 'string') { try { o = JSON.parse(o); } catch (e) { /* keep string */ } }
    if (Array.isArray(o)) o = o[0];
    if (o && typeof o === 'object' && o.response !== undefined) o = o.response;
    let val = null;
    if (typeof o === 'number' && Number.isFinite(o)) val = o;
    else if (typeof o === 'string' && o.trim() !== '' && Number.isFinite(Number(o))) val = Number(o);
    const ti = s.action.toolInput;
    let input = typeof ti === 'string' ? ti : (ti && ti.input !== undefined ? String(ti.input) : '');
    if (!input.trim()) {
      const ml = Array.isArray(s.action.messageLog) ? s.action.messageLog : [];
      const tcs = ml.flatMap((m) => (m && (m.tool_calls || (m.kwargs && m.kwargs.tool_calls) || (m.lc_kwargs && m.lc_kwargs.tool_calls))) || []);
      const tc = tcs.find((t) => t && (s.action.toolCallId ? t.id === s.action.toolCallId : /calculator/i.test(String(t.name || ''))));
      if (tc && tc.args && tc.args.input !== undefined) input = String(tc.args.input);
    }
    return { input, observed: val, failed: val === null, raw_observation: clip(typeof s.observation === 'string' ? s.observation : JSON.stringify(s.observation), 120) };
  });
  audit.calculator_calls = calc;
  audit.calculator_called = calc.length > 0;
  audit.calculator_failed_calls = calc.filter((c) => c.failed).length;
  audit.calculator_required = audit.known_effort_subtotal !== null;
  if (audit.calculator_required) {
    // A call is total evidence only if its expression is a plain sum of exactly the extracted estimates AND its observed result equals the recomputed total.
    const estTerms = actions.filter((a) => a.estimated_hours !== null).map((a) => a.estimated_hours).sort((x, y) => x - y);
    const isTotalCall = (c) => {
      // Accept whitespace and harmless enclosing parentheses, never hidden subtraction/multiplication.
      const e=String(c.input || '').replace(/[()\s]/g,'');
      if (!/^\d+(?:\.\d+)?(?:\+\d+(?:\.\d+)?)*$/.test(e)) return false;
      const terms=e.split('+').map(Number).sort((x,y)=>x-y);
      return terms.length===estTerms.length && terms.every((t,i)=>close(t,estTerms[i]));
    };
    const hit = calc.find((c) => !c.failed && isTotalCall(c) && close(c.observed, knownSubtotal));
    if (hit) {
      audit.calculator_observed_result = hit.observed;
    } else if (!calc.length) {
      addTech('CALCULATOR_EVIDENCE', 'Effort estimates were extracted, but no Calculator tool call appears in the agent trace. The total is not tool-verified.');
    } else if (calc.every((c) => c.failed)) {
      addTech('CALCULATOR_EVIDENCE', 'The Calculator tool was called but returned no usable number. The total is not tool-verified.');
    } else {
      addTech('CALCULATOR_EVIDENCE', 'No Calculator call added the extracted effort estimates to the independently recomputed known total (' + fmt(knownSubtotal) + ' h). Calculator calls seen: ' + calc.filter((c) => !c.failed).map((c) => c.input + ' = ' + c.observed).join('; ') + '.');
    }
    if (teamComparable) {
      const m = calc.find((c) => {
        const e=String(c.input || '').replace(/[()\s]/g,'');
        const p=e.match(/^(\d+(?:\.\d+)?)-(\d+(?:\.\d+)?)$/);
        return !c.failed && p && close(Number(p[1]),team.hours) && close(Number(p[2]),knownSubtotal) && close(c.observed,audit.team_margin);
      });
      audit.calculator_margin_observed = m ? m.observed : null;
      if (!m) addTech('CALCULATOR_MARGIN_EVIDENCE', 'No Calculator call verified comparable team capacity minus estimated task effort.');
    }
  }
}

// 7. Business issues
if (schemaOk) {
  if (actions.length === 0) biz.push({ code: 'NO_ACTIONS', message: 'No confirmed action items were found in the notes.', question: 'Which commitments were confirmed? Please send the complete notes (or complete updated notes) with owner, deadline, and effort per action.' });
  const noOwner = actions.filter((a) => a.owner === null);
  const noDue = actions.filter((a) => a.due_text === null);
  noOwner.forEach((a) => biz.push({ code: 'MISSING_OWNER', message: 'Action ' + a.id + ' (' + clip(a.task, 60) + ') has no assigned owner.', question: null }));
