const readTbl = (rows) => (rows.length ? '<div class="tbl-wrap"><table class="tbl"><caption class="caption">Deterministic snapshot reads made by the workflow for the checked version</caption><thead><tr><th scope="col">Table</th><th scope="col">Result</th><th scope="col">Record IDs</th><th scope="col">Retrieved</th><th scope="col">Newest source update</th></tr></thead><tbody>' + rows.map((t) => '<tr><td><code>' + E(t.table) + '</code></td><td>' + (t.success ? E(t.result_count) + ' row(s)' + (t.truncated ? ' (limit reached: incomplete)' : '') : 'Failed: ' + E(t.error)) + '</td><td>' + E((t.record_ids || []).join(', ') || 'none') + '</td><td>' + fmtDate(t.retrieved_at) + '</td><td>' + fmtDate(t.newest_source_update) + '</td></tr>').join('') + '</tbody></table></div>' : '<p class="empty">No read evidence stored.</p>');
const control = '<section id="control"><h2><span class="sec">H</span>Commitment Control Center</h2>' +
  '<div class="note">Operational readiness is calculated in code: projected load = remaining hours of distinct confirmed open commitments + genuinely new proposed hours; margin = recorded available hours &minus; projected load. <strong>available_hours</strong> is project-allocated usable capacity before register commitments for the same project and period. It does not prove overall availability across other projects or calendars. Readiness is separate from AI review and from human approval.</div>' +
  '<div class="card"><p class="caption">' + E(checkedCases.length) + ' case(s) with Week 3 checks; ' + E(notChecked) + ' case(s) without them are shown as NOT CHECKED (never READY).</p></div>' +
  (checkedCases.length ? checkedCases.map((c) => { const r = c.readiness; return '<div class="card"><h3><code>' + E(c.case_id) + '</code> ' + testTag(c) + demoTag(c) + ' <span class="muted-t">checked version v' + E(r.checked_version) + (r.planning_period ? ' &middot; period ' + E(r.planning_period.start) + ' to ' + E(r.planning_period.end) : '') + '</span></h3>' + badges(c) +
    (r.owners.length ? '<h4>Existing work + proposed work versus recorded capacity</h4>' + ownerBars(r) + '<div class="tbl-wrap"><table class="tbl"><thead><tr><th scope="col">Owner</th><th scope="col">Existing confirmed open</th><th scope="col">New proposed</th><th scope="col">Projected load</th><th scope="col">Recorded capacity</th><th scope="col">Margin</th><th scope="col">Owner result</th></tr></thead><tbody>' + r.owners.map(ownerTable).join('') + '</tbody></table></div><p class="caption">Blank figures are unknown, not zero. Thin marker = recorded capacity.</p>' : '<p class="empty">No resolved owners were checked.</p>') +
    '<div class="grid2"><div><h4>Blocking and unknown reasons</h4>' + list(r.reasons, (x) => '<span class="pill ' + (x.severity === 'BLOCKED' ? 'bad' : (x.severity === 'UNKNOWN' ? 'warn' : 'muted')) + '">' + E(x.severity) + '</span> <code>' + E(x.code) + '</code> ' + E(x.message)) + '</div><div><h4>Clarification questions for a human decision</h4>' + list(r.questions, E) + '</div></div>' +
    '<details><summary>Tool and read evidence (record IDs and freshness)</summary><div class="detail">' + toolTbl(r.tool_evidence) + readTbl(r.read_evidence) + '</div></details></div>'; }).join('') : '<div class="card"><p class="empty">No case has Week 3 readiness results yet.</p></div>') + '</section>';

const overview = '<section id="overview"><h2><span class="sec">A</span>Executive overview</h2>' +
  '<div class="kpis">' +
  kpiCard('Unique cases processed', E(k.total_cases), 'Distinct case_id values; ' + E(d.sources.synthetic_excluded) + ' synthetic excluded') +
  kpiCard('AI-reviewed cases', E(k.ai_reviewed), 'Passed AI checks; human approval is tracked separately.', 'ok') +
  kpiCard('Needs clarification', E(k.needs_clarification), 'Source gaps or conflicts sent back', 'warn') +
