  kpiCard('Versions recorded', E(k.total_versions), 'Draft versions across all cases') +
  kpiCard('Cases revised at least once', E(k.revised_cases), E(k.revised_controlled) + ' of these are controlled tests') +
  kpiCard('Average score - ordinary cases', k.avg_score === null ? '<span class="na">Not available</span>' : E(k.avg_score) + '<span class="unit"> / 5</span>', k.avg_score === null ? 'No evaluated reviews yet' : 'Controlled tests excluded. Rubric score, n = ' + E(k.avg_score_n) + ' case(s). Not an accuracy %.') +
  kpiCard('Human approval decisions', E(k.real_human_approvals), E(ap.drafts_created) + ' Gmail draft(s) created; ' + E(ap.awaiting) + ' pending. Approval is separate from AI review.', 'ok') +
  '</div></section>';

const statusRows = Object.keys(d.status_counts).sort((a, b) => d.status_counts[b] - d.status_counts[a]).map((s) => ({ label: pill(s) + '<code>' + E(s) + '</code>', value: d.status_counts[s], text: E(d.status_counts[s]) + ' (' + E(Math.round((d.status_counts[s] / Math.max(1, k.total_cases)) * 100)) + '%)', cls: sMeta(s).cls }));
const outcomes = '<section id="outcomes"><h2><span class="sec">B</span>Case outcome analytics</h2><div class="card">' +
  (empty ? '<p class="empty">No case records yet. Run the Yellowdig Processor to populate this chart.</p>' : '<p class="caption">Counts of unique cases by stored review_status (n = ' + E(k.total_cases) + '). Versions are not counted here.</p>' + bars(statusRows)) +
  '</div></section>';

const scoredCases = d.cases.filter((c) => c.first_score !== null);
const qualityRows = scoredCases.map((c) => ({ label: '<code>' + E(c.case_id) + '</code>' + (c.controlled ? ' <span class="tag test">TEST</span>' : ''), value: c.last_score, marker: c.first_score !== c.last_score ? c.first_score : null, text: (c.first_score !== null && c.revised && c.first_score_version !== c.last_score_version ? E(c.first_score) + ' &rarr; ' : '') + E(c.last_score) + ' / 5', cls: c.versions.length && c.versions[c.versions.length - 1].gate === 'PASS' ? 'ok' : 'bad' }));
const revRows = d.cases.map((c) => ({ label: '<code>' + E(c.case_id) + '</code>', value: Math.max(0, c.version_rows - 1), text: E(Math.max(0, c.version_rows - 1)) + ' revision(s)', cls: c.controlled ? 'test' : 'info' }));
const findingsHtml = d.findings.length ? '<table class="tbl"><thead><tr><th>Case</th><th>Version</th><th>Severity</th><th>Code</th><th>Explanation</th><th>Required fix</th></tr></thead><tbody>' + d.findings.map((f) => '<tr><td><code>' + E(f.case_id) + '</code>' + (f.controlled ? ' <span class="tag test">TEST</span>' : '') + '</td><td>v' + E(f.version) + '</td><td><span class="pill ' + (f.severity === 'minor' ? 'muted' : 'bad') + '">' + E(f.severity || 'n/a') + '</span></td><td><code>' + E(f.code) + '</code></td><td>' + E(f.explanation) + '</td><td>' + E(f.fix) + '</td></tr>').join('') + '</tbody></table>' : '<p class="empty">No reviewer findings recorded.</p>';
const quality = '<section id="quality"><h2><span class="sec">C</span>AI quality analytics</h2>' +
  '<div class="note">Reviewer scores are a 1&ndash;5 rubric judgment by the Agent 2 reviewer (gate threshold 4.5). They are <strong>not</strong> a measured factual-accuracy percentage.</div>' +
  '<div class="grid2"><div class="card"><h3>Latest reviewer score by case</h3>' + (qualityRows.length ? '<p class="caption">Bar = latest evaluated score on the 1&ndash;5 scale. A thin marker shows the initial score where it differs. Green = gate PASS.</p>' + bars(qualityRows, { max: 5 }) : '<p class="empty">No evaluated reviewer scores yet.</p>') + '</div>' +
  '<div class="card"><h3>First-draft vs revised pass (ordinary cases)</h3><div class="split">' +
  '<div><div class="big ok">' + E(k.first_draft_pass) + '</div><div class="kpi-sub">Passed on the first draft</div></div>' +
  '<div><div class="big info">' + E(k.revised_pass) + '</div><div class="kpi-sub">Passed after revision</div></div>' +
