  '<div class="card"><h3>Score changes across versions</h3>' + (d.cases.length ? '<div class="trends">' + d.cases.map((c) => '<figure><figcaption><code>' + E(c.case_id) + '</code> ' + testTag(c) + '</figcaption>' + trend(c) + '<div class="kpi-sub">' + (c.score_delta === null ? (c.revised ? 'Change not measurable' : 'Single version: no before/after change') : 'Change: ' + (c.score_delta > 0 ? '+' : '') + E(c.score_delta)) + '</div></figure>').join('') + '</div><p class="caption">Dashed amber line = 4.5 quality threshold. Green dot = PASS, red dot = not passed.</p>' : '<p class="empty">No cases yet.</p>') + '</div>' +
  '<div class="card"><h3>Reviewer findings</h3>' + findingsHtml + '</div></section>';

const caseDetail = (c) => {
