        (ownerRows.length ? '<h4>Individual effort vs supplied capacity</h4><p class="caption">Bar = assigned estimated hours; thin marker = supplied capacity for the same planning period.</p>' + bars(ownerRows, { max: maxCap }) : '<p class="empty">No per-owner capacity supplied.</p>') +
