  }).join('') + '<p class="caption">Capacity is never summed across cases or overlapping planning periods.</p>' : '<div class="card"><p class="empty">No case records yet.</p></div>') + '</section>';

const apRows = Object.keys(d.approval_counts).map((a) => ({ label: apPill(a) + '<code>' + E(a) + '</code>', value: d.approval_counts[a], text: E(d.approval_counts[a]) + ' case(s)', cls: 'muted' }));
const oversight = '<section id="oversight"><h2><span class="sec">G</span>Human oversight</h2><div class="grid2"><div class="card"><h3>Pipeline position (unique cases)</h3><div class="pipeline">' +
  [['AI-reviewed', k.ai_reviewed, 'ok'], ['Needs clarification', k.needs_clarification, 'warn'], ['Awaiting human approval', ap.awaiting, 'warn'], ['Human-approved', k.real_human_approvals, 'ok'], ['Changes requested', d.cases.filter((c) => /CHANGES_REQUESTED/i.test(String(c.approval_status || ''))).length, 'info']].map((p) => '<div class="stage ' + p[2] + '"><div class="big">' + E(p[1]) + '</div><div class="kpi-sub">' + E(p[0]) + '</div></div>').join('') +
  '</div><p class="caption">AI-reviewed means both AI stages passed. It is not human approval.</p></div>' +
  '<div class="card"><h3>Stored approval_status values</h3>' + (apRows.length ? bars(apRows) : '<p class="empty">No cases yet.</p>') +
  '<div class="note ' + (k.approval_events ? 'info' : 'muted') + '">' + (k.approval_events ? E(k.approval_events) + ' approval event(s) recorded.' : '<strong>No approval events recorded.</strong> The saved-case approval lane is included on this canvas, but Gmail setup and a real reviewer response are still required. No human approvals are invented.') + '</div>' +
  '<div class="dl mt">Mean time to recorded approval / decline</div>' + (ap.turnaround_minutes === null ? NM : E(ap.turnaround_minutes) + ' minutes (n=' + E(ap.turnaround_n) + ')') + '</div></div>' +
 '<div class="card"><h3>Approval and feedback history</h3>' + (ap.events.length ? '<div class="tbl-wrap"><table class="tbl"><thead><tr><th>Case / version</th><th>Event</th><th>Recorded</th><th>Feedback</th></tr></thead><tbody>' + ap.events.map(e=>'<tr><td><code>'+E(e.case_id)+'</code> v'+E(e.version)+'</td><td>'+E(e.event_type)+'</td><td>'+fmtDate(e.event_at)+'</td><td>'+pre(e.feedback_text)+'</td></tr>').join('') + '</tbody></table></div>' : '<p class="empty">No events yet. The dashboard never sends a request itself.</p>') + '</div></section>';

const warn = (d.read_errors && d.read_errors.length ? '<div class="note bad" role="alert"><strong>Data could not be fully loaded.</strong> One or more tables failed to read; the report below may be incomplete.</div>' : '') + (d.warnings.length ? '<div class="note warn"><strong>Data-quality notices:</strong><ul class="clean">' + d.warnings.map((w) => '<li>' + E(w) + '</li>').join('') + '</ul></div>' : '');
const css = ':root{--ink:#0f172a;--ink2:#334155;--mut:#64748b;--line:#e2e8f0;--bg:#f1f5f9;--card:#fff;--brand:#1e3a8a;--brand2:#2563eb;--ok:#059669;--okb:#d1fae5;--warn:#b45309;--warnb:#fef3c7;--bad:#b91c1c;--badb:#fee2e2;--info:#1d4ed8;--infob:#dbeafe;--test:#7c3aed;--testb:#ede9fe}' +
