const lines=['## ActionReady Week 2 - Human Review','**Status:** '+String(p.status||'TECHNICAL_REVIEW'),'**Case:** '+String(s.case_id||p.case_id||'Not selected'),
 '**Version:** '+String(s.version??'Not available')];
if(p.status==='PREVIEW_ONLY')lines.push('','Read-only preview. No email, approval record, case mutation or model call occurred.',
