if(!draft||draft.subject!==v.subject||!Array.isArray(draft.action_lines)||[draft.opening,...(draft.action_lines||[]).map(x=>'- '+String(x.text||'')),draft.closing].join('\n\n')!==v.body)fail('Saved body differs from its evaluated structured draft.');
